draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // fixed mindset
  ctx.beginPath();
  ctx.arc(W/4, H/2, 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 - 30);
  ctx.lineTo(W/4, H/2 + 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4 - 30, H/2);
  ctx.lineTo(W/4 + 30, H/2);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Fixed', W/4, H/2 + 40);

  // growth mindset
  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 30 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 - (30 + 10*Math.sin(t)));
  ctx.lineTo(W - W/4, H/2 + (30 + 10*Math.sin(t)));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4 - (30 + 10*Math.sin(t)), H/2);
  ctx.lineTo(W - W/4 + (30 + 10*Math.sin(t)), H/2);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Growth', W - W/4, H/2 + 40);

  // arrow
  ctx.beginPath();
  ctx.moveTo(W/2, H/2);
  ctx.lineTo(W/2 + 50*Math.cos(t), H/2 + 50*Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
